def f(g):
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    h,w=len(g),len(g[0])
    # connected components of non-bg cells (4-conn)
    seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and g[na][nb]==g[i][j]:
                            seen[na][nb]=True; st.append((na,nb))
                comps.append((g[i][j],comp))
    out=[[bg]*w for _ in range(h)]
    for c,comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        R,C=min(rs),min(cs); H=max(rs)-R+1; W=max(cs)-C+1
        # anchor bottom row: keep bottom row cells at their original columns; shift others right by 1
        for p in comp:
            i,j=p
            if i==max(rs): out[i][j]=c
            else: out[i][j+1]=c
    return out
