def match_displacements(gi,go,col):
    h,w=len(gi),len(gi[0])
    inp=sorted((r,c) for r in range(h) for c in range(w) if gi[r][c]==col)
    outs=sorted((r,c) for r in range(h) for c in range(w) if go[r][c]==col)
    rem=set(outs); pairs=[]
    for i,(ri,ci) in enumerate(inp):
        best=None
        for (rj,cj) in outs:
            d=abs(rj-ri)+abs(cj-ci)
            if best is None or d<best[0]: best=(d,rj,cj)
