def f(gi):
    h,w=len(gi),len(gi[0])
    cnt=Ct(v for row in gi for v in row)
    bg=cnt.most_common(1)[0][0]
    # connected components of same color using flood fill (8-connectivity)
    seen=[[False]*w for _ in range(h)]
    comps=[]
    for r in range(h):
        for c in range(w):
            if gi[r][c]!=bg and not seen[r][c]:
                col=gi[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            na,nb=a+dr,b+dc
                            if 0<=na<h and 0<=nb<w and not seen[na][nb] and gi[na][nb]==col:
                                seen[na][nb]=True; q.append((na,nb))
                comps.append((col,cells))
    res=[[bg]*w for _ in range(h)]
    for col,cells in comps:
        rs=[a for a,b in cells]; mx=max(rs)
        moved={(a,b+1) for a,b in cells if a<mx}
        unmoved={(a,b) for a,b in cells if a==mx}
        for (a,b),v in {(a,b):col for a,b in moved}.items(): pass
        # place moved cells
        for a,b in moved: res[a][b+1]=col
        for a,b in unmoved: res[a][b]=col
    return res

